CREATE UNIQUE INDEX IF NOT EXISTS ix_tags_name ON tags (name);
CREATE UNIQUE INDEX IF NOT EXISTS ix_projects_name ON projects (name);
CREATE UNIQUE INDEX IF NOT EXISTS ix_api_tokens_token_hash ON api_tokens (token_hash);
CREATE UNIQUE INDEX IF NOT EXISTS ix_auth_sessions_token_hash ON auth_sessions (token_hash);
CREATE INDEX IF NOT EXISTS ix_sync_tombstones_version ON sync_tombstones (version);
CREATE INDEX IF NOT EXISTS ix_notes_name ON notes (name);
CREATE INDEX IF NOT EXISTS ix_reminders_note_pending ON reminders (note_id, reviewed_at, deleted_at, remind_at);
CREATE INDEX IF NOT EXISTS ix_notes_deleted_project ON notes (deleted_at, project_id);
CREATE INDEX IF NOT EXISTS ix_note_tags_tag_id ON note_tags (tag_id);
CREATE TRIGGER IF NOT EXISTS notes_fts_after_insert AFTER INSERT ON notes BEGIN INSERT INTO notes_fts(rowid, name, content) VALUES (new.id, new.name, new.content); END;
CREATE TRIGGER IF NOT EXISTS notes_fts_after_delete AFTER DELETE ON notes BEGIN INSERT INTO notes_fts(notes_fts, rowid, name, content) VALUES ('delete', old.id, old.name, old.content); END;
CREATE TRIGGER IF NOT EXISTS notes_fts_after_update AFTER UPDATE OF name, content ON notes BEGIN INSERT INTO notes_fts(notes_fts, rowid, name, content) VALUES ('delete', old.id, old.name, old.content); INSERT INTO notes_fts(rowid, name, content) VALUES (new.id, new.name, new.content); END;
CREATE UNIQUE INDEX IF NOT EXISTS ix_notes_uid ON notes (uid);
CREATE UNIQUE INDEX IF NOT EXISTS ix_projects_uid ON projects (uid);
CREATE UNIQUE INDEX IF NOT EXISTS ix_tags_uid ON tags (uid);
CREATE UNIQUE INDEX IF NOT EXISTS ix_reminders_uid ON reminders (uid);
CREATE INDEX IF NOT EXISTS ix_notes_sync_version ON notes (sync_version);
CREATE INDEX IF NOT EXISTS ix_projects_sync_version ON projects (sync_version);
CREATE INDEX IF NOT EXISTS ix_tags_sync_version ON tags (sync_version);
CREATE INDEX IF NOT EXISTS ix_settings_sync_version ON settings (sync_version);
CREATE TRIGGER IF NOT EXISTS sync_notes_after_insert AFTER INSERT ON notes BEGIN UPDATE sync_state SET version = version + 1 WHERE id = 1; UPDATE notes SET sync_version = (SELECT version FROM sync_state WHERE id = 1) WHERE id = new.id; DELETE FROM sync_tombstones WHERE kind = 'note' AND uid = new.uid; INSERT OR REPLACE INTO sync_echoes (kind, uid, version) SELECT 'note', new.uid, version FROM sync_state WHERE id = 1 AND applying = 1 AND new.uid IS NOT NULL; END;
CREATE TRIGGER IF NOT EXISTS sync_notes_after_update AFTER UPDATE ON notes WHEN new.sync_version IS old.sync_version BEGIN UPDATE sync_state SET version = version + 1 WHERE id = 1; UPDATE notes SET sync_version = (SELECT version FROM sync_state WHERE id = 1) WHERE id = new.id; INSERT OR REPLACE INTO sync_echoes (kind, uid, version) SELECT 'note', new.uid, version FROM sync_state WHERE id = 1 AND applying = 1 AND new.uid IS NOT NULL; END;
CREATE TRIGGER IF NOT EXISTS sync_notes_after_delete AFTER DELETE ON notes BEGIN UPDATE sync_state SET version = version + 1 WHERE id = 1; INSERT OR REPLACE INTO sync_tombstones (kind, uid, version) VALUES ('note', old.uid, (SELECT version FROM sync_state WHERE id = 1)); INSERT OR REPLACE INTO sync_echoes (kind, uid, version) SELECT 'note', old.uid, version FROM sync_state WHERE id = 1 AND applying = 1 AND old.uid IS NOT NULL; END;
CREATE TRIGGER IF NOT EXISTS sync_projects_after_insert AFTER INSERT ON projects BEGIN UPDATE sync_state SET version = version + 1 WHERE id = 1; UPDATE projects SET sync_version = (SELECT version FROM sync_state WHERE id = 1) WHERE id = new.id; DELETE FROM sync_tombstones WHERE kind = 'project' AND uid = new.uid; INSERT OR REPLACE INTO sync_echoes (kind, uid, version) SELECT 'project', new.uid, version FROM sync_state WHERE id = 1 AND applying = 1 AND new.uid IS NOT NULL; END;
CREATE TRIGGER IF NOT EXISTS sync_projects_after_update AFTER UPDATE ON projects WHEN new.sync_version IS old.sync_version BEGIN UPDATE sync_state SET version = version + 1 WHERE id = 1; UPDATE projects SET sync_version = (SELECT version FROM sync_state WHERE id = 1) WHERE id = new.id; INSERT OR REPLACE INTO sync_echoes (kind, uid, version) SELECT 'project', new.uid, version FROM sync_state WHERE id = 1 AND applying = 1 AND new.uid IS NOT NULL; END;
