CREATE TRIGGER IF NOT EXISTS sync_tags_after_update AFTER UPDATE ON tags WHEN new.sync_version IS old.sync_version BEGIN UPDATE sync_state SET version = version + 1 WHERE id = 1; UPDATE tags SET sync_version = (SELECT version FROM sync_state WHERE id = 1) WHERE id = new.id; INSERT OR REPLACE INTO sync_echoes (kind, uid, version) SELECT 'tag', new.uid, version FROM sync_state WHERE id = 1 AND applying = 1 AND new.uid IS NOT NULL; END;
