CREATE TRIGGER IF NOT EXISTS sync_settings_after_update AFTER UPDATE ON settings WHEN new.sync_version IS old.sync_version BEGIN UPDATE sync_state SET version = version + 1 WHERE id = 1; UPDATE settings SET sync_version = (SELECT version FROM sync_state WHERE id = 1) WHERE id = new.id; INSERT OR REPLACE INTO sync_echoes (kind, uid, version) SELECT 'settings', 'settings', version FROM sync_state WHERE id = 1 AND applying = 1 AND 'settings' IS NOT NULL; END;
CREATE TRIGGER IF NOT EXISTS sync_reminders_after_insert AFTER INSERT ON reminders BEGIN UPDATE sync_state SET version = version + 1 WHERE id = 1; UPDATE notes SET sync_version = (SELECT version FROM sync_state WHERE id = 1) WHERE id = new.note_id; INSERT OR REPLACE INTO sync_echoes (kind, uid, version) SELECT 'note', (SELECT uid FROM notes WHERE id = new.note_id), version FROM sync_state WHERE id = 1 AND applying = 1 AND (SELECT uid FROM notes WHERE id = new.note_id) IS NOT NULL; END;
CREATE TRIGGER IF NOT EXISTS sync_reminders_after_update AFTER UPDATE ON reminders BEGIN UPDATE sync_state SET version = version + 1 WHERE id = 1; UPDATE notes SET sync_version = (SELECT version FROM sync_state WHERE id = 1) WHERE id = new.note_id; INSERT OR REPLACE INTO sync_echoes (kind, uid, version) SELECT 'note', (SELECT uid FROM notes WHERE id = new.note_id), version FROM sync_state WHERE id = 1 AND applying = 1 AND (SELECT uid FROM notes WHERE id = new.note_id) IS NOT NULL; END;
