CREATE TRIGGER IF NOT EXISTS sync_note_tags_after_insert AFTER INSERT ON note_tags BEGIN UPDATE sync_state SET version = version + 1 WHERE id = 1; UPDATE notes SET sync_version = (SELECT version FROM sync_state WHERE id = 1) WHERE id = new.note_id; INSERT OR REPLACE INTO sync_echoes (kind, uid, version) SELECT 'note', (SELECT uid FROM notes WHERE id = new.note_id), version FROM sync_state WHERE id = 1 AND applying = 1 AND (SELECT uid FROM notes WHERE id = new.note_id) IS NOT NULL; END;
